from __future__ import annotations

def count_fires(spec: str, blackouts: list[tuple[int, int]], a: int, b: int) -> int:
    def _num(s: str, cap: int) -> int:
        if not s:
            raise ValueError
        val = 0
        for ch in s:
            if not ('0' <= ch <= '9'):
                raise ValueError
            if val <= cap:
                val = val * 10 + (ord(ch) - 48)
                if val > cap:
                    val = cap + 1
        return val

    def _add_terms(field: str, max_value: int, dest: list[bool]) -> None:
        for term in field.split(','):
            if not term:
                raise ValueError

            parts = term.split('/')
            if len(parts) == 1:
                base = term
                step = None
            elif len(parts) == 2:
                base, step_s = parts
                step = _num(step_s, max_value + 1)
                if step <= 0:
                    raise ValueError
            else:
                raise ValueError

            if base == '*':
                if step is None:
                    for v in range(max_value + 1):
                        dest[v] = True
                else:
                    for v in range(0, max_value + 1, step):
                        dest[v] = True

            elif '-' in base:
                n_s, m_s = base.split('-')
                if len(n_s + m_s) == 0:
                    raise ValueError
                n = _num(n_s, max_value)
                m = _num(m_s, max_value)
                if n > max_value or m > max_value or n > m:
                    raise ValueError

                if step is None:
                    for v in range(n, m + 1):
                        dest[v] = True
                else:
                    for v in range(n, m + 1, step):
                        dest[v] = True

            else:
                n = _num(base, max_value)
                if n > max_value:
                    raise ValueError
                if step is None:
                    dest[n] = True
                else:
                    for v in range(n, max_value + 1, step):
                        dest[v] = True

    fields = spec.split()
    if len(fields) != 3:
        raise ValueError

    minute = [False] * 60
    hour = [False] * 24
    weekday = [False] * 7

    _add_terms(fields[0], 59, minute)
    _add_terms(fields[1], 23, hour)
    _add_terms(fields[2], 6, weekday)

    if b <= a:
        return 0

    WEEK = 10080
    prefix = [0] * (WEEK + 1)

    for t in range(WEEK):
        if (
            minute[t % 60]
            and hour[(t // 60) % 24]
            and weekday[(t // 1440) % 7]
        ):
            prefix[t + 1] = prefix[t] + 1
        else:
            prefix[t + 1] = prefix[t]

    week_count = prefix[WEEK]

    def count_upto(x: int) -> int:
        return (x // WEEK) * week_count + prefix[x % WEEK]

    total = count_upto(b) - count_upto(a)

    intervals = []
    for s, e in blackouts:
        if e <= a or s >= b:
            continue
        if s < a:
            s = a
        if e > b:
            e = b
        if s < e:
            intervals.append((s, e))

    if intervals:
        intervals.sort()
        blocked = 0
        cur_l, cur_r = intervals[0]

        for l, r in intervals[1:]:
            if l <= cur_r:
                if r > cur_r:
                    cur_r = r
            else:
                blocked += count_upto(cur_r) - count_upto(cur_l)
                cur_l, cur_r = l, r

        blocked += count_upto(cur_r) - count_upto(cur_l)
        total -= blocked

    return total
