class FairQueue:
    WAITING = 0
    PAUSED = 1
    RUNNING = 2

    def __init__(self, aging: int, cap: int):
        if aging < 1:
            raise ValueError("aging must be >= 1")
        if cap < 0:
            raise ValueError("cap must be >= 0")

        self.aging = aging
        self.cap = cap
        self._jobs = {}
        self._next_seq = 0

    def _waiting_entries(self, t: int):
        entries = []
        aging = self.aging
        cap = self.cap

        for name, job in self._jobs.items():
            if job.state == self.WAITING:
                waited = job.waited + (t - job.since)
                effective = job.base + min(cap, waited // aging)
                entries.append((-effective, -waited, job.seq, name))

        entries.sort()
        return entries

    def submit(self, job: str, priority: int, t: int):
        if job in self._jobs:
            raise ValueError("Job name already in use")

        self._jobs[job] = _Job(priority, 0, t, self.WAITING, self._next_seq)
        self._next_seq += 1

    def start(self, t: int):
        entries = self._waiting_entries(t)

        if not entries:
            return None

        name = entries[0][3]
        job = self._jobs[name]

        job.waited += t - job.since
        job.state = self.RUNNING
        job.since = None

        return name

    def finish(self, job: str, t: int):
        job_obj = self._jobs.get(job)

        if job_obj is None or job_obj.state != self.RUNNING:
            raise KeyError(job)

        del self._jobs[job]

    def requeue(self, job: str, t: int):
        job_obj = self._jobs.get(job)

        if job_obj is None or job_obj.state != self.RUNNING:
            raise KeyError(job)

        job_obj.base -= 1
        job_obj.since = t
        job_obj.state = self.WAITING
        job_obj.seq = self._next_seq
        self._next_seq += 1

    def pause(self, job: str, t: int) -> bool:
        job_obj = self._jobs.get(job)

        if job_obj is None or job_obj.state not in (self.WAITING, self.PAUSED):
            raise KeyError(job)

        if job_obj.state == self.PAUSED:
            return False

        job_obj.waited += t - job_obj.since
        job_obj.since = None
        job_obj.state = self.PAUSED
        return True

    def resume(self, job: str, t: int) -> bool:
        job_obj = self._jobs.get(job)

        if job_obj is None or job_obj.state not in (self.WAITING, self.PAUSED):
            raise KeyError(job)

        if job_obj.state == self.PAUSED:
            job_obj.since = t
            job_obj.state = self.WAITING
            return True

        return False

    def cancel(self, job: str) -> bool:
        if job in self._jobs:
            del self._jobs[job]
            return True

        return False

    def queue(self, t: int):
        entries = self._waiting_entries(t)
        return [(name, -neg_effective) for neg_effective, neg_waited, seq, name in entries]
