def match_route(pattern: str, path: str):
    if not pattern.startswith('/') or not path.startswith('/'):
        raise ValueError("Both pattern and path must start with '/'")

    def valid_name(name: str) -> bool:
        if not name:
            return False
        for ch in name:
            if not (
                'a' <= ch <= 'z'
                or 'A' <= ch <= 'Z'
                or '0' <= ch <= '9'
                or ch == '_'
            ):
                return False
        return True

    pattern_segments = pattern[1:].split('/')
    path_segments = path[1:].split('/')

    tokens = []
    used_names = set()

    for segment in pattern_segments:
        if segment.startswith(':'):
            if segment.endswith('?'):
                name = segment[1:-1]
                kind = 'opt'
            else:
                name = segment[1:]
                kind = 'req'

            if not valid_name(name) or name in used_names:
                raise ValueError("Invalid or duplicate name in pattern")

            used_names.add(name)
            tokens.append((kind, name, ''))

        elif segment.startswith('#'):
            name = segment[1:]

            if not valid_name(name) or name in used_names:
                raise ValueError("Invalid or duplicate name in pattern")

            used_names.add(name)
            tokens.append(('digit', name, ''))

        elif segment.startswith('*'):
            name = segment[1:]

            if not valid_name(name) or name in used_names:
                raise ValueError("Invalid or duplicate name in pattern")

            used_names.add(name)
            tokens.append(('star', name, ''))

        else:
            tokens.append(('literal', None, segment))

    n = len(path_segments)
    m = len(tokens)

    non_empty = [seg != '' for seg in path_segments]
    digits = []
    for seg in path_segments:
        ok = bool(seg)
        if ok:
            for ch in seg:
                if ch < '0' or ch > '9':
                    ok = False
                    break
        digits.append(ok)

    # feasible[i][p] == 1 iff tokens[i:] can match path_segments[p:]
    feasible = [bytearray(n + 1) for _ in range(m + 1)]
    feasible[m][n] = 1

    for i in range(m - 1, -1, -1):
        kind, _, literal = tokens[i]
        row = feasible[i]
        nxt = feasible[i + 1]

        if kind == 'literal':
            for p in range(n):
                if path_segments[p] == literal:
                    row[p] = nxt[p + 1]

        elif kind == 'req':
            for p in range(n):
                if non_empty[p]:
                    row[p] = nxt[p + 1]

        elif kind == 'digit':
            for p in range(n):
                if digits[p]:
                    row[p] = nxt[p + 1]

        elif kind == 'opt':
            for p in range(n):
                if nxt[p] or (non_empty[p] and nxt[p + 1]):
                    row[p] = 1
            row[n] = 1 if nxt[n] else 0

        else:  # star
            running = 0
            for p in range(n, -1, -1):
                if nxt[p]:
                    running = 1
                row[p] = running

    if not feasible[0][0]:
        return None

    pos = 0
    result = {}

    for i, (kind, name, literal) in enumerate(tokens):
        nxt = feasible[i + 1]

        if kind == 'literal':
            if pos >= n or path_segments[pos] != literal:
                return None
            pos += 1

        elif kind == 'digit':
            if pos >= n or not digits[pos]:
                return None
            result[name] = int(path_segments[pos])
            pos += 1

        elif kind == 'req':
            if pos >= n or not non_empty[pos]:
                return None
            result[name] = path_segments[pos]
            pos += 1

        elif kind == 'opt':
            if nxt[pos]:
                result[name] = None
            elif pos < n and non_empty[pos] and nxt[pos + 1]:
                result[name] = path_segments[pos]
                pos += 1
            else:
                return None

        else:  # star
            q = pos
            while q <= n and not nxt[q]:
                q += 1

            if q > n:
                return None

            result[name] = path_segments[pos:q]
            pos = q

    return result if pos == n else None
