from typing import List, Tuple, Optional


def ferry_plan(
    routes: List[Tuple[str, str, int, int, int]],
    src: str,
    dst: str,
    t0: int
) -> Optional[Tuple[int, int]]:
    if src == dst:
        return (t0, 0)

    port_to_id = {}

    def get_id(name: str) -> int:
        if name not in port_to_id:
            port_to_id[name] = len(port_to_id)
        return port_to_id[name]

    for a, b, _, _, _ in routes:
        get_id(a)
        get_id(b)

    s = get_id(src)
    d = get_id(dst)
    n = len(port_to_id)

    adj: List[List[Tuple[int, int, int, int]]] = [[] for _ in range(n)]
    for a, b, first, every, dur in routes:
        u = port_to_id[a]
        v = port_to_id[b]
        if u != v:
            adj[u].append((v, first, every, dur))

    INF = 10**30

    def next_departure(t: int, first: int, every: int) -> int:
        if t <= first:
            return first
        return first + ((t - first + every - 1) // every) * every

    # prev[v] = earliest arrival at v using at most the previous number of ferries.
    # history[k] = earliest arrival at dst using at most k ferries.
    prev = [INF] * n
    prev[s] = t0

    history = [INF] * n
    history[0] = t0 if s == d else INF

    for k in range(1, n):
        curr = prev.copy()  # also use fewer than k ferries

        for u in range(n):
            t = prev[u]
            if t == INF:
                continue

            for v, first, every, dur in adj[u]:
                arrival = next_departure(t, first, every) + dur
                if arrival < curr[v]:
                    curr[v] = arrival

        history[k] = curr[d]
        prev = curr

    earliest = prev[d]
    if earliest == INF:
        return None

    for k in range(n):
        if history[k] == earliest:
            return (earliest, k)

    return (earliest, n - 1)
